#!/bin/sh
# install-vkbasalt.sh <preset> — write ~/.config/vkBasalt/vkBasalt.conf for
# one ghostcrtty preset, with the fx path resolved to this checkout.
# Generated by transpile_reshade.py.
set -eu
here="$(cd "$(dirname "$0")" && pwd)"
preset="${1:?usage: install-vkbasalt.sh <preset-name> (see vkBasalt/*.conf)}"
src="$here/vkBasalt/$preset.conf"
[ -f "$src" ] || { echo "no such preset conf: $src" >&2; exit 1; }
dest="${XDG_CONFIG_HOME:-$HOME/.config}/vkBasalt"
mkdir -p "$dest"
sed -e "s|@GHOSTCRTTY_FX@|$here/Shaders/ghostcrtty.fx|" \
    -e "s|@GHOSTCRTTY_DIR@|$here/Shaders|" "$src" \
    > "$dest/vkBasalt.conf"
echo "installed $preset -> $dest/vkBasalt.conf"
echo "run your Vulkan app with ENABLE_VKBASALT=1"
